import{_ as a,a0 as m,w as p,s as l,I as s,x as t,a1 as n,A as o,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"如何在 Linux 上从 NetworkManager 切换为 systemd-network | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上从 NetworkManager 切换为 systemd-network | LCTT (201511) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上从 NetworkManager 切换为 systemd-network | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上从 NetworkManager 切换为 systemd-network | LCTT (201511) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201511/20150831 How to switch from NetworkManager to systemd-networkd on Linux","title":"如何在 Linux 上从 NetworkManager 切换为 systemd-network","tag":"201511","desc":""},"relativePath":"201511/20150831 How to switch from NetworkManager to systemd-networkd on Linux.md","filePath":"[post].md"}'),i={name:"201511/20150831 How to switch from NetworkManager to systemd-networkd on Linux.md"};function w(k,e,y,u,g,f){const r=m("Link");return p(),l("div",null,[e[27]||(e[27]=s("h1",{id:"如何在-linux-上从-networkmanager-切换为-systemd-network",tabindex:"-1"},[t("如何在 Linux 上从 NetworkManager 切换为 systemd-network "),s("a",{class:"header-anchor",href:"#如何在-linux-上从-networkmanager-切换为-systemd-network","aria-label":"Permalink to “如何在 Linux 上从 NetworkManager 切换为 systemd-network”"},"​")],-1)),s("p",null,[e[1]||(e[1]=t("在 Linux 世界里，对 ",-1)),n(r,{href:"http://xmodulo.com/use-systemd-system-administration-debian.html"},{default:o(()=>[...e[0]||(e[0]=[t("systemd",-1)])]),_:1}),e[2]||(e[2]=t(" 的采用一直是激烈争论的主题，它的支持者和反对者之间的战火仍然在燃烧。到了今天，大部分主流 Linux 发行版都已经采用了 systemd 作为默认的初始化（init）系统。",-1))]),e[28]||(e[28]=d("<p>正如其作者所说，作为一个 “从未完成、从未完善、但一直追随技术进步” 的系统，systemd 已经不只是一个初始化进程，它被设计为一个更广泛的系统以及服务管理平台，这个平台是一个包含了不断增长的核心系统进程、库和工具的生态系统。</p><p><strong>systemd</strong> 的其中一部分是 <strong>systemd-networkd</strong>，它负责 systemd 生态中的网络配置。使用 systemd-networkd，你可以为网络设备配置基础的 DHCP/静态 IP 网络。它还可以配置虚拟网络功能，例如网桥、隧道和 VLAN。systemd-networkd 目前还不能直接支持无线网络，但你可以使用 wpa_supplicant 服务配置无线适配器，然后把它和 <strong>systemd-networkd</strong> 联系起来。</p><p>在很多 Linux 发行版中，NetworkManager 仍然作为默认的网络配置管理器。和 NetworkManager 相比，<strong>systemd-networkd</strong> 仍处于积极的开发状态，还缺少一些功能。例如，它还不能像 NetworkManager 那样能让你的计算机在任何时候通过多种接口保持连接。它还没有为更高层面的脚本编程提供 ifup/ifdown 钩子函数。但是，systemd-networkd 和其它 systemd 组件（例如用于域名解析的 <strong>resolved</strong>、NTP 的<strong>timesyncd</strong>，用于命名的 udevd）结合的非常好。随着时间增长，<strong>systemd-networkd</strong>只会在 systemd 环境中扮演越来越重要的角色。</p>",3)),s("p",null,[e[4]||(e[4]=t("如果你对 ",-1)),e[5]||(e[5]=s("strong",null,"systemd-networkd",-1)),e[6]||(e[6]=t(" 的进步感到高兴，从 NetworkManager 切换到 systemd-networkd 是值得你考虑的一件事。如果你强烈反对 systemd，对 NetworkManager 或",-1)),n(r,{href:"http://xmodulo.com/disable-network-manager-linux.html"},{default:o(()=>[...e[3]||(e[3]=[t("基础网络服务",-1)])]),_:1}),e[7]||(e[7]=t("感到很满意，那也很好。",-1))]),e[29]||(e[29]=d(`<p>但对于那些想尝试 systemd-networkd 的人，可以继续看下去，在这篇指南中学会在 Linux 中怎么从 NetworkManager 切换到 systemd-networkd。</p><h3 id="需求" tabindex="-1">需求 <a class="header-anchor" href="#需求" aria-label="Permalink to “需求”">​</a></h3><p>systemd 210 及其更高版本提供了 systemd-networkd。因此诸如 Debian 8 &quot;Jessie&quot; (systemd 215)、 Fedora 21 (systemd 217)、 Ubuntu 15.04 (systemd 219) 或更高版本的 Linux 发行版和 systemd-networkd 兼容。</p><p>对于其它发行版，在开始下一步之前先检查一下你的 systemd 版本。</p><pre><code>$ systemctl --version
</code></pre><h3 id="从-networkmanager-切换到-systemd-networkd" tabindex="-1">从 NetworkManager 切换到 Systemd-networkd <a class="header-anchor" href="#从-networkmanager-切换到-systemd-networkd" aria-label="Permalink to “从 NetworkManager 切换到 Systemd-networkd”">​</a></h3><p>从 NetworkManager 切换到 systemd-networkd 其实非常简答（反过来也一样）。</p><p>首先，按照下面这样先停用 NetworkManager 服务，然后启用 systemd-networkd。</p><pre><code>$ sudo systemctl disable NetworkManager
$ sudo systemctl enable systemd-networkd
</code></pre><p>你还要启用 <strong>systemd-resolved</strong> 服务，systemd-networkd用它来进行域名解析。该服务还实现了一个缓存式 DNS 服务器。</p><pre><code>$ sudo systemctl enable systemd-resolved
$ sudo systemctl start systemd-resolved
</code></pre><p>当启动后，<strong>systemd-resolved</strong> 就会在 /run/systemd 目录下某个地方创建它自己的 resolv.conf。但是，把 DNS 解析信息存放在 /etc/resolv.conf 是更普遍的做法，很多应用程序也会依赖于 /etc/resolv.conf。因此为了兼容性，按照下面的方式创建一个到 /etc/resolv.conf 的符号链接。</p><pre><code>$ sudo rm /etc/resolv.conf
$ sudo ln -s /run/systemd/resolve/resolv.conf /etc/resolv.conf
</code></pre><h3 id="用-systemd-networkd-配置网络连接" tabindex="-1">用 systemd-networkd 配置网络连接 <a class="header-anchor" href="#用-systemd-networkd-配置网络连接" aria-label="Permalink to “用 systemd-networkd 配置网络连接”">​</a></h3><p>要用 systemd-networkd 配置网络服务，你必须指定带.network 扩展名的配置信息文本文件。这些网络配置文件保存到 /etc/systemd/network 并从这里加载。当有多个文件时，systemd-networkd 会按照字母顺序一个个加载并处理。</p><p>首先创建 /etc/systemd/network 目录。</p><pre><code>$ sudo mkdir /etc/systemd/network
</code></pre><h4 id="dhcp-网络" tabindex="-1">DHCP 网络 <a class="header-anchor" href="#dhcp-网络" aria-label="Permalink to “DHCP 网络”">​</a></h4><p>首先来配置 DHCP 网络。对于此，先要创建下面的配置文件。文件名可以任意，但记住文件是按照字母顺序处理的。</p><pre><code>$ sudo vi /etc/systemd/network/20-dhcp.network
</code></pre><hr><pre><code>[Match]
Name=enp3*

[Network]
DHCP=yes
</code></pre><p>正如你上面看到的，每个网络配置文件包括了一个或多个 “sections”，每个 “section”都用 [XXX] 开头。每个 section 包括了一个或多个键值对。<code>[Match]</code> 部分决定这个配置文件配置哪个（些）网络设备。例如，这个文件匹配所有名称以 ens3 开头的网络设备（例如 enp3s0、 enp3s1、 enp3s2 等等）对于匹配的接口，然后启用 [Network] 部分指定的 DHCP 网络配置。</p><h3 id="静态-ip-网络" tabindex="-1">静态 IP 网络 <a class="header-anchor" href="#静态-ip-网络" aria-label="Permalink to “静态 IP 网络”">​</a></h3><p>如果你想给网络设备分配一个静态 IP 地址，那就新建下面的配置文件。</p><pre><code>$ sudo vi /etc/systemd/network/10-static-enp3s0.network
</code></pre><hr><pre><code>[Match]
Name=enp3s0

[Network]
Address=192.168.10.50/24
Gateway=192.168.10.1
DNS=8.8.8.8
</code></pre><p>正如你猜测的， enp3s0 接口地址会被指定为 192.168.10.50/24，默认网关是 192.168.10.1， DNS 服务器是 8.8.8.8。这里微妙的一点是，接口名 enp3s0 事实上也匹配了之前 DHCP 配置中定义的模式规则。但是，根据词汇顺序，文件 &quot;10-static-enp3s0.network&quot; 在 &quot;20-dhcp.network&quot; 之前被处理，对于 enp3s0 接口静态配置比 DHCP 配置有更高的优先级。</p><p>一旦你完成了创建配置文件，重启 systemd-networkd 服务或者重启机器。</p><pre><code>$ sudo systemctl restart systemd-networkd
</code></pre><p>运行以下命令检查服务状态：</p><pre><code>$ systemctl status systemd-networkd
$ systemctl status systemd-resolved
</code></pre><p><img src="https://farm1.staticflickr.com/719/21010813392_76abe123ed_c.jpg" alt=""></p><h3 id="用-systemd-networkd-配置虚拟网络设备" tabindex="-1">用 systemd-networkd 配置虚拟网络设备 <a class="header-anchor" href="#用-systemd-networkd-配置虚拟网络设备" aria-label="Permalink to “用 systemd-networkd 配置虚拟网络设备”">​</a></h3><p><strong>systemd-networkd</strong> 同样允许你配置虚拟网络设备，例如网桥、VLAN、隧道、VXLAN、绑定等。你必须在用 .netdev 作为扩展名的文件中配置这些虚拟设备。</p><p>这里我展示了如何配置一个桥接接口。</p><h4 id="linux-网桥" tabindex="-1">Linux 网桥 <a class="header-anchor" href="#linux-网桥" aria-label="Permalink to “Linux 网桥”">​</a></h4><p>如果你想创建一个 Linux 网桥(br0) 并把物理接口(eth1) 添加到网桥，你可以新建下面的配置。</p><pre><code>$ sudo vi /etc/systemd/network/bridge-br0.netdev
</code></pre><hr><pre><code>[NetDev]
Name=br0
Kind=bridge
</code></pre><p>然后按照下面这样用 .network 文件配置网桥接口 br0 和从接口 eth1。</p><pre><code>$ sudo vi /etc/systemd/network/bridge-br0-slave.network
</code></pre><hr><pre><code>[Match]
Name=eth1

[Network]
Bridge=br0
</code></pre><hr><pre><code>$ sudo vi /etc/systemd/network/bridge-br0.network
</code></pre><hr><pre><code>[Match]
Name=br0

[Network]
Address=192.168.10.100/24
Gateway=192.168.10.1
DNS=8.8.8.8
</code></pre><p>最后，重启 systemd-networkd。</p><pre><code>$ sudo systemctl restart systemd-networkd
</code></pre>`,52)),s("p",null,[e[9]||(e[9]=t("你可以用 ",-1)),n(r,{href:"http://xmodulo.com/how-to-configure-linux-bridge-interface.html"},{default:o(()=>[...e[8]||(e[8]=[t("brctl 工具",-1)])]),_:1}),e[10]||(e[10]=t(" 来验证是否创建好了网桥 br0。",-1))]),e[30]||(e[30]=s("h3",{id:"总结",tabindex:"-1"},[t("总结 "),s("a",{class:"header-anchor",href:"#总结","aria-label":"Permalink to “总结”"},"​")],-1)),e[31]||(e[31]=s("p",null,"当 systemd 誓言成为 Linux 的系统管理器时，有类似 systemd-networkd 的东西来管理网络配置也就不足为奇。但是在现阶段，systemd-networkd 看起来更适合于网络配置相对稳定的服务器环境。对于桌面/笔记本环境，它们有多种临时有线/无线接口，NetworkManager 仍然是比较好的选择。",-1)),s("p",null,[e[12]||(e[12]=t("对于想进一步了解 systemd-networkd 的人，可以参考官方",-1)),n(r,{href:"http://www.freedesktop.org/software/systemd/man/systemd.network.html"},{default:o(()=>[...e[11]||(e[11]=[t("man 手册",-1)])]),_:1}),e[13]||(e[13]=t("了解完整的支持列表和关键点。",-1))]),e[32]||(e[32]=s("hr",null,null,-1)),s("p",null,[e[15]||(e[15]=t("via: ",-1)),n(r,{href:"http://xmodulo.com/switch-from-networkmanager-to-systemd-networkd.html"},{default:o(()=>[...e[14]||(e[14]=[t("http://xmodulo.com/switch-from-networkmanager-to-systemd-networkd.html",-1)])]),_:1})]),s("p",null,[e[19]||(e[19]=t("作者：",-1)),n(r,{href:"http://xmodulo.com/author/nanni"},{default:o(()=>[...e[16]||(e[16]=[t("Dan Nanni",-1)])]),_:1}),e[20]||(e[20]=t(" 译者：",-1)),n(r,{href:"http://mutouxiaogui.cn/blog"},{default:o(()=>[...e[17]||(e[17]=[t("ictlyh",-1)])]),_:1}),e[21]||(e[21]=t(" 校对：",-1)),n(r,{href:"https://github.com/wxy"},{default:o(()=>[...e[18]||(e[18]=[t("wxy",-1)])]),_:1})]),s("p",null,[e[24]||(e[24]=t("本文由 ",-1)),n(r,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[22]||(e[22]=[t("LCTT",-1)])]),_:1}),e[25]||(e[25]=t(" 原创编译，",-1)),n(r,{href:"https://linux.cn/"},{default:o(()=>[...e[23]||(e[23]=[t("Linux中国",-1)])]),_:1}),e[26]||(e[26]=t(" 荣誉推出",-1))])])}const h=a(i,[["render",w]]);export{b as __pageData,h as default};
